#!/usr/bin/env node
/**
 * Tests for workflows/dev-loop.js: the review fixes of flow v2 (block reader, carried findings, questions on every
 * implementer call, fix-round gate, quoting, soft scope of a sole final reader).
 * Zero dependencies — `node:test` on Node 18+; the shared harness is tools/dev-loop.harness.mjs.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS, ARGS_M, review, finding, impl, gate, tasksOf, HELPER, reviewLabels } from './dev-loop.harness.mjs';

const implCalls = (calls) => calls.filter(c => c.opts.agentType === 'implementer');
const green = (extra = {}) => impl({ gate: gate('green'), ...extra });
const treeless = (extra = {}) => impl({ gate: gate('green', { tree: '' }), ...extra });   // no block delta to read
const V_ARGS = { ...ARGS_M, verify: 'node --test x' };
const T2 = (tree, churn = 3) => ({ tree, files: ['src/Orders/OrdersQuery.cs'], churn });
const readerA = (calls) => calls.filter(c => /^block \d+ · reader A$/.test(c.opts.label ?? ''));
const scopeAt = (extra = {}) => finding({ category: 'scope', title: 'unrequested rename of a helper', ...extra });
const TDD_ARGS = { ...V_ARGS, unit: 'node --test u', plan: { tasks: [{ ...tasksOf(1)[0], tdd: true, criteria: ['the total adds the tax'] }] } };
const dataQuestion = [{ text: 'Who owns the data?', default: 'the caller', why: 'two owners', reversible: true, axis: 'data' }];

test('given size S with a verify command, when the loop runs, then no reader A reads the block: only the final reader A reads', async () => {
  // Given
  const queue = [review([])];
  // When
  const { calls } = await run({ ...ARGS, verify: 'node --test x' }, queue, [green()]);
  // Then
  assert.deepEqual(readerA(calls), []);
  assert.deepEqual(reviewLabels(calls), ['reviewer A · round 1 · code']);
});

test('given a reader A finding outside the perimeter that the change did not cause, when the block ends, then it is reported as out of scope and tracked nowhere', async () => {
  // Given
  const queue = [review([], [finding({ path: HELPER })]), review([])];
  // When
  const { out } = await run(V_ARGS, queue, [green()]);
  // Then
  assert.equal(out.status, 'OK');
  assert.deepEqual(out.open, []);
  assert.deepEqual(out.carried, []);
  assert.deepEqual(out.outOfScope.map(o => o.path), [HELPER]);
});

test('given a tests-first call that raises a data question, when it returns, then the loop stalls with the question', async () => {
  // Given
  const impls = [impl({ gate: gate('red-proven'), questions: dataQuestion })];
  // When
  const { out } = await run(TDD_ARGS, [], impls);
  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'question');
  assert.deepEqual(out.stall.questions.map(q => q.text), ['Who owns the data?']);
});

test('given a gate fix call that raises a data question, when it returns, then the loop stalls with the question', async () => {
  // Given
  const impls = [impl({ gate: gate('red', { test: 'A fails' }) }), green({ questions: dataQuestion })];
  // When
  const { out } = await run(V_ARGS, [], impls);
  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'question');
});

test('given a reader A fix call that raises a data question, when it returns, then the loop stalls with the question', async () => {
  // Given
  const queue = [review([], [finding()])];
  // When
  const { out } = await run(V_ARGS, queue, [green(), green({ questions: dataQuestion })]);
  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'question');
});

test('given a gate fix call that raises a reversible logic question, when it returns, then its default is applied and listed', async () => {
  // Given
  const questions = [{ text: 'Which sort order?', default: 'newest first', why: 'unsaid', reversible: true, axis: 'logic' }];
  const impls = [impl({ gate: gate('red', { test: 'A fails' }) }), green({ questions }), green(), green()];
  // When
  const { out, calls } = await run(V_ARGS, [review([]), review([])], impls);
  // Then
  assert.equal(out.status, 'OK');
  assert.deepEqual(out.defaultsApplied, [{ block: 1, question: 'Which sort order?', default: 'newest first' }]);
  assert.ok(implCalls(calls).some(c => c.opts.label === 'implement the change (gate fix) (answers)'));
});

const fixRoundRun = (fixGate, extra = {}) => run(V_ARGS, [review([], [finding()])], [treeless(), impl({ gate: fixGate, snapshot: T2('t2', 10) }), treeless({ snapshot: T2('t3', 10) })], extra);

test('given a fix round whose gate is still running, when it returns, then the loop stalls with gate-running, not green-to-red', async () => {
  // Given / When
  const { out, calls } = await fixRoundRun(gate('running'));
  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'gate-running');
  assert.deepEqual(reviewLabels(calls, 2), []);
});

test('given a fix round that edits a proven test, when its gate says red: tests changed, then the loop stalls as tests-changed for the owner and no verifier runs', async () => {
  // Given / When
  const { out, calls } = await fixRoundRun(gate('red: tests changed', { test: 'tests/Tax.test.cs' }));
  // Then
  assert.equal(out.stall.why, 'tests-changed');
  assert.match(out.stall.reason, /tests\/Tax\.test\.cs/);
  assert.match(out.resume, /Ask the user/);
  assert.deepEqual(reviewLabels(calls, 2), []);
});

test('given a fix round whose gate times out, when it returns, then the loop stalls with gate-timeout and the fix is not retried', async () => {
  // Given / When
  const { out, calls } = await fixRoundRun(gate('red: timeout', { test: 'Slow' }));
  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'gate-timeout');
  assert.equal(implCalls(calls).filter(c => c.opts.label.startsWith('fix round')).length, 1);
});

test('given a fix round whose gate is red for an edit outside the perimeter, when it returns, then it is no green-to-red stall: the next fix round is told the files to revert', async () => {
  // Given / When
  const { out, calls } = await fixRoundRun(gate('red: scope', { outside: [HELPER] }));
  // Then
  assert.notEqual(out.stall?.why, 'green-to-red');
  const second = calls.find(c => c.opts.label === 'fix round 2 findings');
  assert.ok(second.prompt.includes(HELPER));
});

test('given a verify command with the dotnet logger form, when the gate command is built, then it is wrapped in single quotes and the double quotes pass', async () => {
  // Given
  const verify = 'dotnet test --logger "console;verbosity=normal"';
  // When
  const { calls } = await run({ ...V_ARGS, verify }, [], [green()]);
  // Then
  assert.ok(implCalls(calls)[0].prompt.includes(`--test '${verify}'`));
});

test('given a verify command with a single quote, when the loop starts, then it answers with an error and calls no agent', async () => {
  // Given / When
  const { out, calls } = await run({ ...V_ARGS, verify: "node -e '1'" }, [], [green()]);
  // Then
  assert.match(out, /verify command contains a single quote/);
  assert.equal(calls.length, 0);
});

test('given a unit command with a single quote, when the loop starts, then it answers with an error and calls no agent', async () => {
  // Given / When
  const { out, calls } = await run({ ...V_ARGS, unit: "node -e '1'" }, [], [green()]);
  // Then
  assert.match(out, /unit command contains a single quote/);
  assert.equal(calls.length, 0);
});

test('given no verify command, when an M run ends, then one gap says the blocks were not read by reader A; an S run or a verify run has none', async () => {
  // Given / When
  const none = await run(ARGS_M, [review([])]);
  const small = await run(ARGS, [review([])]);
  const gated = await run(V_ARGS, [review([]), review([])], [green()]);
  // Then
  const line = 'no verify: blocks were not read by reader A';
  assert.deepEqual(none.out.gaps.filter(g => g === line), [line]);
  assert.equal(small.out.gaps.includes(line), false);
  assert.equal(gated.out.gaps.includes(line), false);
});

test('given a reader A finding inside the perimeter, when the reader A fix is briefed, then it carries the scope-revert and reproduce-first rules of the fix round', async () => {
  // Given
  const queue = [review([], [scopeAt({ confidence: 'PLAUSIBLE' })]), review([])];
  // When
  const { calls } = await run(V_ARGS, queue, [green(), green()]);
  // Then
  const prompt = calls.find(c => c.opts.label === 'implement the change (reader A fix)').prompt;
  assert.match(prompt, /A "scope" finding means revert that hunk/);
  assert.match(prompt, /REPRODUCE FIRST/);
  assert.match(prompt, /A1\.1 \[P2\].*\(PLAUSIBLE: REPRODUCE FIRST\)/);
});

const previewAnswer = async () => {
  const first = await run({ ...V_ARGS, preview: 'the order list page /orders' }, [], [treeless()]);
  return [{ round: 0, answers: [{ text: first.out.stall.questions[0].text, answer: 'order by date' }] }];
};

test('given a preview answer that is a direction, when the implementer runs again, then its brief carries the gate command and a report without the gate line stalls', async () => {
  // Given
  const resolutions = await previewAnswer();
  // When
  const { out, calls } = await run({ ...V_ARGS, preview: 'the order list page /orders', resolutions }, [review([])], [treeless(), impl()]);
  // Then
  const again = calls.find(c => c.opts.label === 'implement the change (preview feedback)');
  assert.match(again.prompt, /paste its last output line as "gate"/);
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'verify-not-run');
});

test('given M, when its only final reader runs, then it is labelled by its role: whole diff', async () => {
  // Given / When
  const { calls } = await run(ARGS_M, [review([])]);
  // Then
  assert.deepEqual(reviewLabels(calls, 1), ['reviewer B · round 1 · whole diff']);
});

test('given M, when its only final reader raises a CONFIRMED scope finding, then it blocks and is fixed', async () => {
  // Given
  const queue = [review([], [scopeAt({ confidence: 'CONFIRMED' })]), review([{ id: 'F1', status: 'closed' }])];
  // When
  const { calls } = await run(ARGS_M, queue, [impl(), impl({ snapshot: T2('t2', 10) })]);
  // Then
  assert.deepEqual(implCalls(calls).map(c => c.opts.label), ['implement the change', 'fix round 1 findings']);
});

test('given the coverage rerun at M that goes to B alone, when it runs, then its effort is medium and its model unchanged', async () => {
  // Given
  const files = Array.from({ length: 4 }, (_, i) => `src/Orders/F${i}.cs`);
  const queue = [review([], [], ['src/Orders/F0.cs']), review([])];
  // When
  const { calls } = await run({ ...ARGS_M, perimeter: { files: ['src/Orders/'] } }, queue, [impl({ files, snapshot: { tree: 't1', files, churn: 3 } })]);
  // Then
  const readers = calls.filter(c => /^reviewer B/.test(c.opts.label ?? ''));
  assert.deepEqual(readers.map(c => `${c.opts.model}:${c.opts.effort}`), ['sonnet:high', 'sonnet:medium']);
});
